import os,sys,io,time,json,hashlib,base64,zlib,subprocess,signal,fcntl,importlib.metadata
from pathlib import Path
os.environ['KERAS_BACKEND']='tensorflow'
os.environ.setdefault('TF_CPP_MIN_LOG_LEVEL','2')
os.environ.setdefault('TF_DETERMINISTIC_OPS','1')
os.environ.setdefault('CUBLAS_WORKSPACE_CONFIG',':4096:8')
os.environ.setdefault('PYTHONHASHSEED','42')
os.environ.setdefault('TOKENIZERS_PARALLELISM','false')

def _ensure_environment():
    pinned={'numpy':'2.1.3','pandas':'2.3.3','scipy':'1.15.3','scikit-learn':'1.6.1'}
    if OPTIONS['MODE']=='RUN':pinned.update({'tensorflow':'2.20.0','keras':'3.13.2'})
    to_install=[]
    for package,want in pinned.items():
        try:current=importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:current=None
        if current!=want:to_install.append(f'{package}=={want}')
    try:importlib.metadata.version('matplotlib')
    except importlib.metadata.PackageNotFoundError:to_install.append('matplotlib')
    if to_install:
        if not OPTIONS['INSTALL_MATCHING_ENVIRONMENT']:
            raise RuntimeError('Pinned dependencies missing: '+str(to_install))
        print('Reconciling pinned packages before fresh workers:',to_install,flush=True)
        subprocess.run([sys.executable,'-m','pip','install','--quiet','--disable-pip-version-check',*to_install],check=True)
    for package,want in pinned.items():
        if importlib.metadata.version(package)!=want:raise RuntimeError('Pinned package mismatch: '+package)

def _run_one_cell():
    if OPTIONS['MODE'] not in ('RUN','REPORT_ONLY'):raise ValueError('MODE must be RUN or REPORT_ONLY')
    if OPTIONS['RUN_SEEDS']!=[42,2026,3407,123,777]:
        raise ValueError('All five frozen seeds required for complete LOSO')
    if not (1<=float(OPTIONS['MAX_RUNTIME_HOURS'])<=12):
        raise ValueError('MAX_RUNTIME_HOURS should not exceed Kaggle session limit')
    _ensure_environment()
    root=Path(OPTIONS['OUTPUT_DIR']);root.mkdir(parents=True,exist_ok=True)
    lockpath=root/'.onecell.lock'
    with lockpath.open('a+') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise RuntimeError('An F06 LOSO job already owns this output directory')
        runtime=root/'runtime';runtime.mkdir(exist_ok=True)
        for name,package in PAYLOAD.items():
            raw=zlib.decompress(base64.b64decode(package['data']))
            if hashlib.sha256(raw).hexdigest()!=package['sha256']:
                raise RuntimeError('Embedded source corrupted: '+name)
            path=runtime/name
            if path.exists() and hashlib.sha256(path.read_bytes()).hexdigest()!=package['sha256']:
                raise RuntimeError('Conflicting previous code: choose another OUTPUT_DIR')
            if not path.exists():
                temporary=path.with_name(path.name+'.tmp');temporary.write_bytes(raw);os.replace(temporary,path)
        options=dict(OPTIONS,STARTED_AT=time.time())
        settings=runtime/'options.json';settings.write_text(json.dumps(options,indent=2))
        env=os.environ.copy();env['PYTHONUNBUFFERED']='1'
        proc=subprocess.Popen([sys.executable,str(runtime/'f06_loso_driver.py'),'--settings',str(settings)],
            stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1,env=env,start_new_session=True)
        try:
            for line in proc.stdout:print(line,end='',flush=True)
            code=proc.wait()
        except KeyboardInterrupt:
            os.killpg(proc.pid,signal.SIGINT)
            for line in proc.stdout:print(line,end='',flush=True)
            code=proc.wait()
        print('COMPLETE NATIVE MODEL FOLDER:',root,flush=True)
        print('SMALL RESULTS ZIP:',root.parent/(root.name+'_RESULTS_ONLY.zip'),flush=True)
        if code==75:
            print('PARTIAL — saved checkpoints are resumable. Save the COMPLETE native folder and rerun this exact cell.',flush=True)
        elif code!=0:raise RuntimeError('F06 LOSO driver failed. See traceback and worker logs. Completed native fits are retained.')
_run_one_cell()
